"""Package upgrade campaigns: pins from requirements files and uv.lock, per-repo status."""
from __future__ import annotations

from datetime import datetime, timezone

import pytest

from collectors import campaigns, waves
from dashboard.lib.config import get_config

NOW = datetime(2026, 10, 21, tzinfo=timezone.utc)

REQUIREMENTS = """\
#
# This file is autogenerated by pip-compile
#
certifi==2026.7.22
    # via requests
charset-normalizer==3.4.0
Certifi == 2026.10.19 ; python_version >= "3.12"
"""

UV_LOCK = """\
version = 1
revision = 3

[[package]]
name = "certifi"
version = "2026.7.22"

[[package]]
name = "requests"
version = "2.32.0"
dependencies = [{ name = "certifi" }]

[[package]]
name = "pytest"
version = "8.0.0"

[[package]]
name = "my-lib"
source = { editable = "." }
dependencies = [{ name = "requests" }]

[package.dev-dependencies]
test = [{ name = "pytest" }]
"""

DEV_ONLY_UV_LOCK = """\
version = 1

[[package]]
name = "certifi"
version = "2026.7.22"

[[package]]
name = "my-lib"
source = { virtual = "." }

[package.dev-dependencies]
test = [{ name = "certifi" }]
"""


@pytest.fixture(scope="module")
def certifi() -> dict:
    return get_config("campaigns")["campaigns"]["certifi_2026_10"]


@pytest.mark.parametrize(
    ("path", "expected"),
    [
        ("uv.lock", True),
        ("requirements/base.txt", True),
        ("requirements/edx/development.txt", True),
        ("requirements.txt", True),
        ("requirements/base.in", False),
        ("docs/requirements.txt", False),
        ("setup.py", False),
    ],
)
def test_pin_files(path, expected):
    assert campaigns.is_pin_file(path) is expected


def test_requirements_pins_match_normalized_names_only():
    assert campaigns.requirements_pins(REQUIREMENTS, "certifi") == ["2026.7.22", "2026.10.19"]
    assert campaigns.requirements_pins("certifi-extra==1.0\n", "certifi") == []


def test_uv_pin_reachable_from_project_is_runtime():
    assert campaigns.uv_pins(UV_LOCK, "certifi") == [("2026.7.22", True)]


def test_uv_pin_only_in_dev_group_is_not_runtime():
    assert campaigns.uv_pins(DEV_ONLY_UV_LOCK, "certifi") == [("2026.7.22", False)]


def test_invalid_uv_lock_has_no_pins():
    assert campaigns.uv_pins("not = [toml", "certifi") == []


def test_runtime_comes_from_the_file_name(certifi):
    base = campaigns.pins("requirements/edx/base.txt", "certifi==2026.7.22\n", certifi)
    dev = campaigns.pins("requirements/dev.txt", "certifi==2026.7.22\n", certifi)
    assert [pin["runtime"] for pin in base + dev] == [True, False]


def _pin(version: str, runtime: bool = True, path: str = "requirements/base.txt") -> dict:
    return {"path": path, "version": version, "runtime": runtime}


def test_repo_without_pins_is_not_applicable(certifi):
    assert campaigns.repo_status("openedx/frontend", [], certifi, None, now=NOW)["status"] == waves.NOT_APPLICABLE


def test_repo_at_floor_is_done(certifi):
    record = campaigns.repo_status("openedx/a", [_pin("2026.10.19"), _pin("2027.1.1")], certifi, None, now=NOW)
    assert record["status"] == waves.DONE
    assert record["below_floor"] == []
    assert record["runtime_exposed"] is False


def test_one_stale_pin_keeps_repo_open(certifi):
    stale = _pin("2026.7.22", runtime=False, path="requirements/dev.txt")
    record = campaigns.repo_status("openedx/a", [_pin("2026.10.19"), stale], certifi, None, now=NOW)
    assert record["status"] == waves.NOT_STARTED
    assert record["below_floor"] == [stale]
    assert record["runtime_exposed"] is False


def test_open_pr_is_reported_with_age(certifi):
    pr = {"url": "https://github.com/openedx/a/pull/5", "title": "bump certifi", "createdAt": "2026-10-11T00:00:00Z"}
    record = campaigns.repo_status("openedx/a", [_pin("2026.7.22")], certifi, pr, now=NOW)
    assert record["status"] == waves.PR_OPEN
    assert record["pr_age_days"] == 10
    assert record["runtime_exposed"] is True


def test_unparseable_version_counts_as_below_floor(certifi):
    assert campaigns.below_floor(_pin("not-a-version"), certifi["min_version"])


@pytest.mark.parametrize(
    ("campaign_id", "title", "matches"),
    [
        ("uv_2026_10", "build(deps): bump uv from 0.13.1 to 0.13.4", True),
        ("uv_2026_10", "build: Upgrade `uv` to 0.13.4", True),
        ("uv_2026_10", "chore(deps): update dependency uv to v0.13.4", True),
        ("uv_2026_10", "uv 0.13.4 bump", True),
        ("uv_2026_10", "build(deps): bump astral-sh/setup-uv from 6 to 7", False),
        ("uv_2026_10", "chore(deps): update dependency uv-build to v0.9", False),
        ("uv_2026_10", "build: migrate to uv", False),
        ("uv_2026_10", "chore: update uv.lock", False),
        ("uv_2026_10", "chore: update CI to install pip via uv", False),
        ("pip_2026_10", "build(deps): Bump pip from 24.2 to 26.2.2 in /requirements", True),
        ("pip_2026_10", "chore: upgrade pip to 26.2.2", True),
        ("pip_2026_10", "chore: upgrade pip-tools to 7.5", False),
        ("pip_2026_10", "chore: update requirements/pip.txt", False),
        ("pip_2026_10", "chore: update CI to install pip via uv", False),
        ("pip_2026_10", "build: switch from pip to uv", False),
        ("pip_2026_10", "chore: use pip to install deps", False),
        ("pip_2026_10", "fix: pin pip to <25", False),
        ("uv_2026_10", "build: use uv to install requirements", False),
        ("uv_2026_10", "ci: run uv tool install tox", False),
        ("uv_2026_10", "Bump uv from 0.12.0 to 0.13.1", False),
        ("pip_2026_10", "chore: pin pip to 24.2", False),
        ("pip_2026_10", "Bump pip from 24.2 to 25.0", False),
        ("pip_2026_10", "chore: upgrade pip to 26.3 for python 3.12", True),
        ("certifi_2026_10", "build: Upgrade `certifi` to latest", True),
        ("certifi_2026_10", "chore: bump certifi from 2026.7.22 to 2026.10.19", True),
        ("certifi_2026_10", "chore: bump certifi from 2026.4.1 to 2026.7.22", False),
    ],
)
def test_campaign_pr_titles(campaign_id, title, matches):
    campaign = get_config("campaigns")["campaigns"][campaign_id]
    pr = {"title": title, "repository": {"nameWithOwner": "openedx/a"}, "createdAt": "2026-10-21T00:00:00Z"}
    assert bool(campaigns.matching_prs([pr], campaign)) is matches
